    55→
    56→public(package) fun new_e_mode_registry(ctx: &mut TxContext): EModeGroupRegistry {
    57→    EModeGroupRegistry {
    58→        next_group_id: 0,
    59→        groups: table::new(ctx)
    60→    }
    61→}
    62→
    63→/// Create a new e mode group and returns the e mode id
    64→public(package) fun new_emode_group(registry: &mut EModeGroupRegistry, oracle_base_token: u8, ctx: &mut TxContext): u8 {
    65→    let next_id = registry.next_group_id;
    66→    assert!(next_id != std::u8::max_value!(), error::max_emode_groups_reached());
